31: const MyPets = () => {
32:   const [pets, setPets] = useState([]);
33:   const [loading, setLoading] = useState(true);
34:   const [user, setUser] = useState(null);
35:   const [token, setToken] = useState('');
36:   const [searchQuery, setSearchQuery] = useState('');
37:   const [selectedSpecies, setSelectedSpecies] = useState('All');
38: 
39:   // Modals state
40:   const [isAddModalOpen, setIsAddModalOpen] = useState(false);
41:   const [isEditModalOpen, setIsEditModalOpen] = useState(false);
42:   const [isViewModalOpen, setIsViewModalOpen] = useState(false);
43:   const [selectedPet, setSelectedPet] = useState(null);
44: 
45:   // Form & Upload state
46:   const [formData, setFormData] = useState(INITIAL_FORM_STATE);
47:   const [uploadingImage, setUploadingImage] = useState(false);
48:   const [formSubmitting, setFormSubmitting] = useState(false);
49:   const [toastMessage, setToastMessage] = useState(null);
50: 
51:   const navigate = useNavigate();
52: 
53:   useEffect(() => {
54:     const storedUser = localStorage.getItem('currentUser');
55:     const storedToken = localStorage.getItem('userToken');
56:     if (!storedUser) {
57:       navigate('/login');
58:       return;
59:     }
60:     const parsedUser = JSON.parse(storedUser);
61:     setUser(parsedUser);
62:     setToken(storedToken || '');
63:     fetchPets(parsedUser);
64:   }, [navigate]);
65: 
66:   const showToast = (msg, type = 'success') => {
67:     setToastMessage({ text: msg, type });
68:     setTimeout(() => setToastMessage(null), 3500);
69:   };
70: 
71:   const fetchPets = async (currentUser) => {
72:     setLoading(true);
73:     try {
74:       const ownerId = currentUser._id || currentUser.id;
75:       const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets?ownerId=${ownerId}`);
76:       if (res.ok) {
77:         const data = await res.json();
78:         setPets(data.data || []);
79:       } else {
80:         console.error('Failed to fetch pets');
81:       }
82:     } catch (err) {
83:       console.error('Error fetching pets:', err);
84:     } finally {
85:       setLoading(false);
86:     }
87:   };
88: 
89:   // ImageKit File Upload Handler
90:   const handleImageUpload = (e) => {
91:     const file = e.target.files[0];
92:     if (!file) return;
93: 
94:     setUploadingImage(true);
95:     const reader = new FileReader();
96:     reader.readAsDataURL(file);
97:     reader.onload = async () => {
98:       try {
99:         const res = await fetch(`${import.meta.env.VITE_API_URL}/api/imagekit/upload`, {
100:           method: 'POST',
101:           headers: { 'Content-Type': 'application/json' },
102:           body: JSON.stringify({
103:             file: reader.result,
104:             fileName: `pet_${Date.now()}_${file.name}`,
105:             folder: '/pets'
106:           })
107:         });
108:         const data = await res.json();
109:         if (res.ok && data.success && data.url) {
110:           setFormData((prev) => ({ ...prev, image: data.url }));
111:           showToast('Image uploaded successfully to ImageKit!');
112:         } else {
113:           showToast(data.message || 'Image upload failed. Ensure your ImageKit keys in Render are valid.', 'error');
114:         }
115:       } catch (err) {
116:         showToast('Image upload error: ' + err.message, 'error');
117:       } finally {
118:         setUploadingImage(false);
119:       }
120:     };
121:   };
122: 
123:   // Open Add Modal
124:   const handleOpenAddModal = () => {
125:     setFormData(INITIAL_FORM_STATE);
126:     setIsAddModalOpen(true);
127:   };
128: 
129:   // Open Edit Modal
130:   const handleOpenEditModal = (pet) => {
131:     setSelectedPet(pet);
132:     setFormData({
133:       name: pet.name || '',
134:       species: pet.species || pet.type || 'Dog',
135:       breed: pet.breed || '',
136:       gender: pet.gender || 'Male',
137:       age: pet.age !== undefined ? pet.age : 1,
138:       ageUnit: pet.ageUnit || 'Years',
139:       weight: pet.weight !== undefined ? pet.weight : 5,
140:       weightUnit: pet.weightUnit || 'kg',
141:       color: pet.color || '',
142:       image: pet.image || '',
143:       description: pet.description || '',
144:       vaccinated: pet.vaccinated !== undefined ? pet.vaccinated : true,
145:       vaccinationDate: pet.vaccinationDate ? new Date(pet.vaccinationDate).toISOString().split('T')[0] : new Date().toISOString().split('T')[0],
146:       healthStatus: pet.healthStatus || 'Healthy',
147:       status: pet.status || 'Available'
148:     });
149:     setIsEditModalOpen(true);
150:   };
151: 
152:   // Submit Add Pet
153:   const handleAddPetSubmit = async (e) => {
154:     e.preventDefault();
155:     setFormSubmitting(true);
156:     try {
157:       const ownerId = user._id || user.id;
158:       const payload = {
159:         ...formData,
160:         type: formData.species, // explicitly set type for the Render backend
161:         ownerId,
162:         ownerName: user.name || '',
163:         ownerEmail: user.email || '',
164:         ownerPhone: user.phone || ''
