166: 
167:       const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets`, {
168:         method: 'POST',
169:         headers: {
170:           'Content-Type': 'application/json',
171:           Authorization: `Bearer ${token}`
172:         },
173:         body: JSON.stringify(payload)
174:       });
175: 
176:       const data = await res.json();
177:       if (res.ok && data.success) {
178:         showToast('Pet registered successfully!');
179:         setIsAddModalOpen(false);
180:         setFormData(INITIAL_FORM_STATE);
181:         fetchPets(user);
182:       } else {
183:         showToast(data.message || 'Failed to add pet', 'error');
