185:     } catch (err) {
186:       showToast('Error registering pet: ' + err.message, 'error');
187:     } finally {
188:       setFormSubmitting(false);
189:     }
190:   };
191: 
192:   // Submit Edit Pet
193:   const handleEditPetSubmit = async (e) => {
194:     e.preventDefault();
195:     if (!selectedPet) return;
196: 
197:     setFormSubmitting(true);
198:     try {
199:       const petId = selectedPet._id || selectedPet.id;
200:       
201:       const payload = {
202:         ...formData,
203:         type: formData.species
204:       };
205: 
206:       const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets/${petId}`, {
207:         method: 'PUT',
208:         headers: {
209:           'Content-Type': 'application/json',
210:           Authorization: `Bearer ${token}`
211:         },
212:         body: JSON.stringify(payload)
213:       });
214: 
215:       const data = await res.json();
216:       if (res.ok && data.success) {
217:         showToast('Pet details updated successfully!');
218:         setIsEditModalOpen(false);
219:         setSelectedPet(null);
220:         fetchPets(user);
221:       } else {
222:         showToast(data.message || 'Failed to update pet', 'error');
223:       }
224:     } catch (err) {
225:       showToast('Error updating pet: ' + err.message, 'error');
226:     } finally {
227:       setFormSubmitting(false);
228:     }
229:   };
230: 
231:   // Delete Pet
232:   const handleDeletePet = async (pet) => {
233:     const petId = pet._id || pet.id;
234:     if (!window.confirm(`Are you sure you want to delete ${pet.name}?`)) return;
235: 
236:     try {
237:       const res = await fetch(`${import.meta.env.VITE_API_URL}/api/pets/${petId}`, {
238:         method: 'DELETE',
239:         headers: {
240:           Authorization: `Bearer ${token}`
241:         }
242:       });
243:       const data = await res.json();
244:       if (res.ok && data.success) {
245:         showToast(`${pet.name} has been removed.`);
246:         fetchPets(user);
247:       } else {
248:         showToast(data.message || 'Failed to delete pet', 'error');
249:       }
