308:               }`}
309:             >
310:               {spec}
311:             </button>
312:           ))}
313:         </div>
314: 
315:         <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-end">
316:           {/* Search Input */}
317:           <div className="relative w-full md:w-64">
318:             <span className="material-symbols-outlined absolute left-3 top-1/2 -translate-y-1/2 text-outline-variant text-[18px]">
